print(not True and False) #False; not True is false and false is false
print(True or False and False) #True; and is evaluated first so expression False and False so expression becomes True or False
print(not (5 > 3)) #False; 5 > 3 is true, not true becomes false
print(10 == 10 and 4 != 4) #False; 10 equals 10, but 4 is the same as 4, that becomes True and False which is false
print(not False or not True) #True; not true equals True not True equals False expression becomes True or false equals True